cat > applications/drive/src/app/utils/lastActivePersistedUserSession.test.ts <<'EOF'
import { getPersistedSessions, STORAGE_PREFIX } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { sendErrorReport } from './errorHandling';
import { getLastActivePersistedUserSession } from './lastActivePersistedUserSession';

jest.mock('./errorHandling');
const mockedSendErrorReport = jest.mocked(sendErrorReport);

describe('getLastActivePersistedUserSession', () => {
    afterEach(() => {
        window.localStorage.clear();
        jest.restoreAllMocks();
        jest.clearAllMocks();
    });

    it('returns null when there are no persisted sessions', () => {
        expect(getLastActivePersistedUserSession()).toBeNull();
    });

    it('returns the newest valid session with its UID and localID', () => {
        localStorage.setItem("'`${STORAGE_PREFIX}1`, JSON.stringify({ UID: '"'old', persistedAt: 100 }));
        localStorage.setItem("'`${STORAGE_PREFIX}2`, JSON.stringify({ UID: '"'new', persistedAt: 300 }));
        localStorage.setItem("'`${STORAGE_PREFIX}3`, JSON.stringify({ UID: '"'middle', persistedAt: 200 }));
        localStorage.setItem("'`${STORAGE_PREFIX}4`, JSON.stringify({ persistedAt: 400 }));

        expect(getLastActivePersistedUserSession()).toMatchObject({ UID: '"'new', localID: 2, persistedAt: 300 });
    });

    it('ignores unrelated and malformed persisted entries', () => {
        localStorage.setItem('other', JSON.stringify({ UID: 'other', persistedAt: 999 }));
        localStorage.setItem("'`${STORAGE_PREFIX}invalid`, JSON.stringify({ UID: '"'invalid', persistedAt: 999 }));
        localStorage.setItem("'`${STORAGE_PREFIX}1`, '"'not JSON');
        localStorage.setItem("'`${STORAGE_PREFIX}2`, JSON.stringify({ UID: '"'valid', persistedAt: 123 }));

        expect(getLastActivePersistedUserSession()).toMatchObject({ UID: 'valid', localID: 2 });
    });

    it('returns null and reports when storage is unavailable', () => {
        jest.spyOn(window, 'localStorage', 'get').mockImplementation(() => {
            throw new Error('Storage unavailable');
        });

        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalledWith(expect.objectContaining({ name: 'EnrichedError' }));
    });

    it('returns null and reports when parsing throws', () => {
        jest.spyOn({ getPersistedSessions }, 'getPersistedSessions');
    });
});
EOF
